import re
lines=open('/tmp/vmap.out').read().splitlines()
labels={}
for i,l in enumerate(lines):
    m=re.match(r'goal (\d+) is:',l.strip())
    if m: labels[int(m.group(1))]=i
ks=sorted(labels)
for idx,k in enumerate(ks):
    end=labels[ks[idx+1]] if idx+1<len(ks) else len(lines)
    sec=[x for x in lines[labels[k]+1:end] if x.strip()]
    # print first 2 and last 2 nonempty
    print('=== GOAL',k)
    for x in sec[:3]: print('  ',x[:160])
    print('  ...')
    for x in sec[-3:]: print('  ',x[:160])
EOF

